const moltenSpiritSheet=new Image();moltenSpiritSheet.assetSrc='assets/molten-spirit-v2.png';
function beginMoltenSpirit(e){let dx=p.x-e.x,dy=p.y-e.y,len=Math.hypot(dx,dy),reach=Math.min(360,len),origin={x:e.x,y:e.y},end={...origin};for(let s=6;s<reach+6;s+=6){let d=Math.min(s,reach),q={x:e.x+dx/(len||1)*d,y:e.y+dy/(len||1)*d};if(!passable(q.x,q.y,18)||!lineClear(end,q,18))break;end=q;}e.state='attack';e.elapsed=0;e.struck=false;e.facing=dx-dy<0?-1:1;e.attack={pattern:'moltenLockedLeap',bespoke:true,windup:1.4,origin,end,last:{...origin},landed:false,crashed:false,crashAt:null};}
const moltenSpiritAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r7e7')return moltenSpiritAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='moltenLockedLeap'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=400&&clear){beginMoltenSpirit(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,88*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.crashed&&!a.landed&&e.elapsed>=.85){let t=e.elapsed>=1.4?1:Math.max(0,(e.elapsed-.85)/.55),q={x:a.origin.x+(a.end.x-a.origin.x)*t,y:a.origin.y+(a.end.y-a.origin.y)*t},dx=q.x-e.x,dy=q.y-e.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/6));for(let j=0;j<n;j++){let x=e.x+dx/n,y=e.y+dy/n;if(!passable(x,y,18)||!lineClear(e,{x,y},18)){a.crashed=true;a.crashAt=e.elapsed;break;}e.x=x;e.y=y;}a.last={x:e.x,y:e.y};if(!a.crashed&&t===1){a.landed=true;e.struck=true;if(dist(e,p)<=105+1e-8&&lineClear(e,p))hurt(88);burst(e.x,e.y,105,'#ffab6b');playSound('impact',e.x,e.y);}}
 if(a.crashed?e.elapsed>=a.crashAt+1.2:e.elapsed>=2.6){e.attack=null;e.state='idle';e.t=2.8;}
};
function moltenSpiritLift(e){let a=e.attack;return e.hp>0&&a?.pattern==='moltenLockedLeap'&&!a.crashed&&!a.landed&&e.elapsed>.85?Math.sin(Math.PI*Math.max(0,Math.min(1,(e.elapsed-.85)/.55)))*80:0;}
const moltenSpiritDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r7e7'||!moltenSpiritSheet.complete||!moltenSpiritSheet.naturalWidth||!moltenSpiritSheet.naturalHeight)return moltenSpiritDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='moltenLockedLeap')f={row:2,col:e.attack.crashed?3:e.elapsed<.85?0:e.elapsed<1.4?1:e.elapsed<1.7?2:3};let q=project(e.x,e.y),sw=moltenSpiritSheet.naturalWidth/4,sh=moltenSpiritSheet.naturalHeight/3,w=270,h=w*sh/sw,anchor=[.85,.82,.84][f.row];ctx.save();ctx.translate(q.x,q.y-moltenSpiritLift(e));ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,moltenSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(moltenSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const moltenSpiritSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r7e7'?170:moltenSpiritSizeBase(e);
const moltenSpiritGroundBase=drawGroundEffects;drawGroundEffects=()=>{moltenSpiritGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r7e7'):enemies)){let a=e.attack;if(e.species!=='r7e7'||e.hp<=0||a?.pattern!=='moltenLockedLeap')continue;if(a.crashed||e.elapsed>=1.7){if(visibleAt(e.x,e.y))groundRing(e.x,e.y,34,'#9bddcf',2);continue;}if(visibleAt(a.end.x,a.end.y))groundRing(a.end.x,a.end.y,105,a.landed?'#ffe1a1':'#e8aa75',a.landed?3:2);if(!a.landed){let q=project(a.origin.x,a.origin.y),r=project(a.end.x,a.end.y);ctx.save();ctx.strokeStyle='#e8aa7555';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(r.x,r.y);ctx.stroke();ctx.restore();if(e.elapsed>=.85)groundRing(e.x,e.y,22,'#dd814c',1);}}};
